import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import { ConfigProvider, Button, Dialog, DatePicker } from '@alifd/next';
import 'antd/dist/antd.css'; // 或者 @alifd/next 样式

function App() {
  const showDialog = () => {
    Dialog.show({
      title: 'Dialog 中的 DatePicker',
      // 在 content 中直接放一个 DatePicker
      content: <DatePicker placeholder="请选择日期" />,  
      onCancel: () => Dialog.hide(),
      onOk: () => Dialog.hide()
    });
  };

  return (
    <ConfigProvider
      // 指定所有浮层统一挂载到 #popup-root 容器
      popupContainer={() => document.getElementById('popup-root')}
    >
      <div style={{ padding: 20 }}>
        <h3>Page 上的 DatePicker（应挂载到 popup-root）</h3>
        <DatePicker placeholder="请选择日期" />

        <div style={{ margin: '24px 0' }}>
          <Button type="primary" onClick={showDialog}>
            打开 Dialog
          </Button>
        </div>

        <h3>Dialog 弹窗</h3>
        <p>点击上方按钮打开 Dialog，Dialog 内的 DatePicker 弹层应该也挂载到 popup-root，但实际上仍挂载到 document.body。</p>
      </div>

      {/* 全局浮层容器 */}
      <div
        id="popup-root"
        style={{
          position: 'relative',
          zIndex: 1000,
          border: '1px dashed #ccc',
          height: 200,
          marginTop: 20
        }}
      />
    </ConfigProvider>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
